void main(void)
{
  unsigned int timer_now;

  CSR_READ(TIMER_VALUE, timer_now);
 
  unsigned int freq = 100;
  unsigned int nco_delta = freq *131.072+0.5;
  unsigned int nco_angle =0;
  unsigned int nco_angle_delta = freq*167772.16+0.5;

  while(1) {
        // bump timer first (4 is the down rate)
        timer_now += DMA_OUT_SIZE * 4;



        make_nco(VMEM_DMA_ADDRESS(nco_data), 1280, nco_angle, nco_delta);
        nco_angle = (nco_angle + nco_angle_delta);
        
        int occupancy;
        while(1) {
          CSR_READ(DMA_2_SCHEDULE_OCCUPANCY, occupancy);
          if(occupancy == 0) {//DMA_2_SCHEDULE_DEPTH
             break;
            }
        }

        while(1) {
          CSR_READ(DMA_1_SCHEDULE_OCCUPANCY, occupancy);
          if(occupancy == 0) {//DMA_2_SCHEDULE_DEPTH
             break;
            }
        }

        xbb_conj_multi_80(VMEM_ADDRESS(config_word_cmul_eq_0f), VMEM_ADDRESS(input_coarse_sync_before_cfo), VMEM_ADDRESS(nco_data), VMEM_ADDRESS(input_coarse_sync_after_cfo));

        dma_out_set_safe(VMEM_DMA_ADDRESS(input_coarse_sync_after_cfo), DMA_OUT_SIZE, timer_now);
    }

}  


